274	// runCleanAll cleans all session data across the repository.
275	func runCleanAll(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
276		s, err := settings.Load(ctx)
277		if err != nil {
278			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to load settings: %v\n", err)
279			s = &settings.EntireSettings{}
280		}
281	
282		// Scoped escape hatch for the v2 enumeration path. The fast path is
283		// near-instantaneous, but a generation whose generation.json is missing
284		// falls back to a go-git tree walk that doesn't honor context
285		// cancellation, so a single Ctrl-C can leave the user stuck. A second
286		// Ctrl-C forces exit. Scoped to clean --all only.
287		stopEscape := installForceExitOnSecondSignal(ctx)
288		defer stopEscape()
289	
290		v2Ctx, cancelV2 := context.WithCancel(ctx)
291		defer cancelV2()
292	
293		var (
294			v2Items    []strategy.CleanupItem
295			v2Warnings []string
296			v2Err      error
297		)
298		v2Done := make(chan struct{})
299		if s.IsCheckpointsV2Enabled() {
300			go func() {
301				defer close(v2Done)
302				v2Items, v2Warnings, v2Err = strategy.ListEligibleV2Generations(v2Ctx, s)
303			}()
304		} else {
305			close(v2Done)
306		}
307	
308		// List all items (sessions, shadow branches) — not just orphaned ones
309		items, err := strategy.ListAllItems(ctx)
310		if err != nil {
311			cancelV2()
312			<-v2Done
313			return fmt.Errorf("failed to list items: %w", err)
314		}
315	
316		// List temp files — skip active-session filter since --all deletes those sessions
317		tempFiles, err := listAllTempFiles(ctx)
318		if err != nil {
319			// Non-fatal: continue with other cleanup items
320			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to list temp files: %v\n", err)
321		}
322	
323		<-v2Done
324		if v2Err != nil {
325			if errors.Is(v2Err, context.Canceled) {
326				return NewSilentError(v2Err)
327			}
328			return fmt.Errorf("failed to list v2 generations: %w", v2Err)
329		}
330		items = append(items, v2Items...)
331		for _, warning := range v2Warnings {
332			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: %s\n", warning)
333		}
334	
335		return runCleanAllWithItems(ctx, cmd, force, dryRun, items, tempFiles)
336	}
