502	// listAllTempFiles returns all files in .entire/tmp/ without filtering.
503	// Used by --all since those sessions are being deleted anyway.
504	func listAllTempFiles(ctx context.Context) ([]string, error) {
505		absDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
506		if err != nil {
507			return nil, fmt.Errorf("failed to resolve temp dir: %w", err)
508		}
509		root, err := os.OpenRoot(absDir)
510		if err != nil {
511			if os.IsNotExist(err) {
512				return nil, nil
513			}
514			return nil, fmt.Errorf("failed to open root: %w", err)
515		}
516		defer root.Close()
517	
518		var files []string
519		err = fs.WalkDir(root.FS(), ".", func(_ string, d fs.DirEntry, err error) error {
520			if err != nil {
521				return err
522			}
523			if d.IsDir() {
524				return nil
525			}
526			files = append(files, d.Name())
527			return nil
528		})
529		if os.IsNotExist(err) {
530			return nil, nil
531		}
532		if err != nil {
533			return nil, fmt.Errorf("failed to list temp dir: %w", err)
534		}
535		return files, nil
536	}
