538	// TempFileDeleteError contains a file name and the error that occurred during deletion.
539	type TempFileDeleteError struct {
540		File string
541		Err  error
542	}
543	
544	// deleteTempFiles removes all files in .entire/tmp/.
545	// Uses os.Root to ensure deletions are confined to the temp directory.
546	// Returns successfully deleted files and any failures with their error reasons.
547	func deleteTempFiles(ctx context.Context, files []string) (deleted []string, failed []TempFileDeleteError) {
548		absDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
549		if err != nil {
550			for _, file := range files {
551				failed = append(failed, TempFileDeleteError{File: file, Err: err})
552			}
553			return nil, failed
554		}
555		root, err := os.OpenRoot(absDir)
556		if err != nil {
557			for _, file := range files {
558				failed = append(failed, TempFileDeleteError{File: file, Err: err})
559			}
560			return nil, failed
561		}
562		defer root.Close()
563	
564		for _, file := range files {
565			if err := root.Remove(file); err != nil {
566				failed = append(failed, TempFileDeleteError{File: file, Err: err})
567			} else {
568				deleted = append(deleted, file)
569			}
570		}
571		return deleted, failed
572	}
