574	// activeSessionsOnCurrentHead returns sessions on the current HEAD
575	// that are in an active phase (ACTIVE).
576	func activeSessionsOnCurrentHead(ctx context.Context) ([]*session.State, error) {
577		repo, err := openRepository(ctx)
578		if err != nil {
579			return nil, err
580		}
581	
582		head, err := repo.Head()
583		if err != nil {
584			return nil, fmt.Errorf("failed to get HEAD: %w", err)
585		}
586		currentHead := head.Hash().String()
587	
588		states, err := strategy.ListSessionStates(ctx)
589		if err != nil {
590			return nil, fmt.Errorf("failed to list session states: %w", err)
591		}
592	
593		var active []*session.State
594		for _, state := range states {
595			if state.BaseCommit != currentHead {
596				continue
597			}
598			if state.Phase.IsActive() {
599				active = append(active, state)
600			}
601		}
602	
603		return active, nil
604	}
