63	// shadowBranchPattern matches shadow branch names in both old and new formats:
64	//   - Old format: entire/<commit[:7+]>
65	//   - New format: entire/<commit[:7+]>-<worktreeHash[:6]>
66	//
67	// The pattern requires at least 7 hex characters for the commit, optionally followed
68	// by a dash and exactly 6 hex characters for the worktree hash.
69	var shadowBranchPattern = regexp.MustCompile(`^entire/[0-9a-fA-F]{7,}(-[0-9a-fA-F]{6})?$`)
70	
71	// IsShadowBranch returns true if the branch name matches the shadow branch pattern.
72	// Shadow branches have the format "entire/<commit-hash>-<worktree-hash>" where the
73	// commit hash is at least 7 hex characters and worktree hash is 6 hex characters.
74	// The "entire/checkpoints/v1" branch is NOT a shadow branch.
75	func IsShadowBranch(branchName string) bool {
76		// Explicitly exclude metadata and trails branches
77		if branchName == paths.MetadataBranchName || branchName == paths.TrailsBranchName {
78			return false
79		}
80		return shadowBranchPattern.MatchString(branchName)
81	}
82	
83	// ListShadowBranches returns all shadow branches in the repository.
84	// Shadow branches match the pattern "entire/<commit-hash>" (7+ hex chars).
85	// The "entire/checkpoints/v1" branch is excluded as it stores permanent metadata.
86	// Returns an empty slice (not nil) if no shadow branches exist.
87	func ListShadowBranches(ctx context.Context) ([]string, error) {
88		repo, err := OpenRepository(ctx)
89		if err != nil {
90			return nil, fmt.Errorf("failed to open git repository: %w", err)
91		}
92	
93		refs, err := repo.References()
94		if err != nil {
95			return nil, fmt.Errorf("failed to get references: %w", err)
96		}
97	
98		var shadowBranches []string
99	
100		err = refs.ForEach(func(ref *plumbing.Reference) error {
101			if err := ctx.Err(); err != nil {
102				return err //nolint:wrapcheck // Propagating context cancellation
103			}
104			// Only look at branch references
105			if !ref.Name().IsBranch() {
106				return nil
107			}
108	
109			// Extract branch name without refs/heads/ prefix
110			branchName := strings.TrimPrefix(ref.Name().String(), "refs/heads/")
111	
112			if IsShadowBranch(branchName) {
113				shadowBranches = append(shadowBranches, branchName)
114			}
115			return nil
116		})
117		if err != nil {
118			return nil, fmt.Errorf("failed to iterate references: %w", err)
119		}
120	
121		// Ensure we return empty slice, not nil
122		if shadowBranches == nil {
123			shadowBranches = []string{}
124		}
125	
126		return shadowBranches, nil
127	}
128	
129	// DeleteShadowBranches deletes the specified branches from the repository.
130	// Returns two slices: successfully deleted branches and branches that failed to delete.
131	// Individual branch deletion failures do not stop the operation - all branches are attempted.
132	func DeleteShadowBranches(ctx context.Context, branches []string) (deleted []string, failed []string, err error) { //nolint:unparam // already present in codebase
133		if len(branches) == 0 {
134			return []string{}, []string{}, nil
135		}
136	
137		for _, branch := range branches {
138			// Use git CLI to delete branches because go-git v5's RemoveReference
139			// doesn't properly persist deletions with packed refs or worktrees
140			if err := DeleteBranchCLI(ctx, branch); err != nil {
141				failed = append(failed, branch)
142				continue
143			}
144	
145			deleted = append(deleted, branch)
146		}
147	
148		return deleted, failed, nil
149	}
150	
151	// ListOrphanedSessionStates returns session state files that are orphaned.
152	// A session state is orphaned if:
153	//   - No checkpoints on entire/checkpoints/v1 reference this session ID
154	//   - No shadow branch exists for the session's base commit
155	//
156	// This is strategy-agnostic as session states are shared by all strategies.
157	func ListOrphanedSessionStates(ctx context.Context) ([]CleanupItem, error) {
158		repo, err := OpenRepository(ctx)
159		if err != nil {
160			return nil, fmt.Errorf("failed to open git repository: %w", err)
161		}
162	
163		// Get all session states
164		store, err := session.NewStateStore(ctx)
165		if err != nil {
166			return nil, fmt.Errorf("failed to create state store: %w", err)
167		}
168	
169		states, err := store.List(ctx)
170		if err != nil {
171			return nil, fmt.Errorf("failed to list session states: %w", err)
172		}
173	
174		if len(states) == 0 {
175			return []CleanupItem{}, nil
176		}
177	
178		// Get all checkpoints to find which sessions have checkpoints
179		cpStore := checkpoint.NewGitStore(repo)
180	
181		sessionsWithCheckpoints := make(map[string]bool)
182		checkpoints, listErr := cpStore.ListCommitted(ctx)
183		if listErr == nil {
184			for _, cp := range checkpoints {
185				sessionsWithCheckpoints[cp.SessionID] = true
186			}
187		}
188	
189		// Get all shadow branches as a set for quick lookup
190		shadowBranches, _ := ListShadowBranches(ctx) //nolint:errcheck // Best effort
191		shadowBranchSet := make(map[string]bool)
192		for _, branch := range shadowBranches {
193			shadowBranchSet[branch] = true
194		}
195	
196		var orphaned []CleanupItem
197		now := time.Now()
198	
199		for _, state := range states {
200			// Skip sessions that started recently - they may be actively in use
201			// but haven't created their first checkpoint yet
202			if now.Sub(state.StartedAt) < sessionGracePeriod {
203				continue
204			}
205	
206			// Check if session has checkpoints on entire/checkpoints/v1
207			hasCheckpoints := sessionsWithCheckpoints[state.SessionID]
208	
209			// Check if shadow branch exists for this session's base commit and worktree
210			// Shadow branches are now worktree-specific: entire/<commit[:7]>-<worktreeHash[:6]>
211			expectedBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
212			hasShadowBranch := shadowBranchSet[expectedBranch]
213	
214			// Session is orphaned if it has no checkpoints AND no shadow branch
215			if !hasCheckpoints && !hasShadowBranch {
216				reason := "no checkpoints or shadow branch found"
217				orphaned = append(orphaned, CleanupItem{
218					Type:   CleanupTypeSessionState,
219					ID:     state.SessionID,
220					Reason: reason,
221				})
222			}
223		}
224	
225		return orphaned, nil
226	}
227	
228	// DeleteOrphanedSessionStates deletes the specified session state files.
229	func DeleteOrphanedSessionStates(ctx context.Context, sessionIDs []string) (deleted []string, failed []string, err error) {
230		if len(sessionIDs) == 0 {
231			return []string{}, []string{}, nil
232		}
233	
234		store, err := session.NewStateStore(ctx)
235		if err != nil {
236			return nil, nil, fmt.Errorf("failed to create state store: %w", err)
237		}
238	
239		for _, sessionID := range sessionIDs {
240			if err := store.Clear(ctx, sessionID); err != nil {
241				failed = append(failed, sessionID)
242			} else {
243				deleted = append(deleted, sessionID)
244			}
245		}
246	
247		return deleted, failed, nil
248	}
