553	func removeTempRefs(repo *git.Repository, refs []plumbing.ReferenceName) {
554		for _, ref := range refs {
555			_ = repo.Storer.RemoveReference(ref) //nolint:errcheck // cleanup is best-effort
556		}
557	}
