349	// WalkCheckpointShards iterates over the two-level shard structure (<id[:2]>/<id[2:]>/)
350	// in a checkpoint tree, calling fn for each checkpoint found. Skips non-directory entries
351	// at both levels (e.g., generation.json at the root). The callback receives the parsed
352	// checkpoint ID and the tree hash of the checkpoint subtree.
353	func WalkCheckpointShards(repo *git.Repository, tree *object.Tree, fn func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error) error {
354		for _, bucketEntry := range tree.Entries {
355			if bucketEntry.Mode != filemode.Dir {
356				continue
357			}
358			if len(bucketEntry.Name) != 2 {
359				continue
360			}
361	
362			bucketTree, err := repo.TreeObject(bucketEntry.Hash)
363			if err != nil {
364				continue
365			}
366	
367			for _, cpEntry := range bucketTree.Entries {
368				if cpEntry.Mode != filemode.Dir {
369					continue
370				}
371	
372				cpID, err := id.NewCheckpointID(bucketEntry.Name + cpEntry.Name)
373				if err != nil {
374					continue
375				}
376	
377				if err := fn(cpID, cpEntry.Hash); err != nil {
378					return err
379				}
380			}
381		}
382		return nil
383	}
