177	// ComputeGenerationTimestampsFromTreesCtx is the cancellable variant of
178	// ComputeGenerationTimestampsFromTrees. The underlying tree walk honors ctx
179	// between checkpoints so long enumerations (e.g. `entire clean --all` across
180	// many archived generations with missing generation.json files) abort
181	// promptly on Ctrl+C.
182	func (s *V2GitStore) ComputeGenerationTimestampsFromTreesCtx(ctx context.Context, rootTreeHash plumbing.Hash, mainTree *object.Tree) (GenerationMetadata, bool, error) {
183		if rootTreeHash == plumbing.ZeroHash {
184			return GenerationMetadata{}, false, nil
185		}
186	
187		rootTree, err := s.repo.TreeObject(rootTreeHash)
188		if err != nil {
189			return GenerationMetadata{}, false, fmt.Errorf("failed to read generation tree: %w", err)
190		}
191	
192		var gen GenerationMetadata
193		found := false
194		missingCheckpointTimestamp := false
195		err = WalkCheckpointShardsCtx(ctx, s.repo, rootTree, func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error {
196			if mainTree != nil {
197				if cpGen, ok := s.checkpointTimestampRangeFromMain(mainTree, cpID); ok {
198					mergeGenerationRange(&gen, &found, cpGen)
199					return nil
200				}
201			}
202	
203			cpTree, treeErr := s.repo.TreeObject(cpTreeHash)
204			if treeErr != nil {
205				missingCheckpointTimestamp = true
206				return nil //nolint:nilerr // Skip unreadable checkpoint trees and fall back to generation.json.
207			}
208			if cpGen, ok := checkpointTimestampRangeFromFullTree(cpTree); ok {
209				mergeGenerationRange(&gen, &found, cpGen)
210				return nil
211			}
212			missingCheckpointTimestamp = true
213			return nil
214		})
215		if err != nil {
216			return GenerationMetadata{}, false, err
217		}
218		if missingCheckpointTimestamp {
219			return GenerationMetadata{}, false, nil
220		}
221	
222		return gen, found, nil
223	}
